import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }

        int[] sumEven = {0};
        long[] productOdd = {1};

        // Lambda to process each element
        java.util.function.IntConsumer process = num -> {
            if (num % 2 == 0) {
                sumEven[0] += num;
            } else {
                productOdd[0] *= num;
            }
        };

        // Process all elements
        for (int num : arr) {
            process.accept(num);
        }

        // Check if there were any odd numbers
        if (productOdd[0] == 1) {
            // Reset to 0 if no odd numbers found (to handle case where 1 is the only odd product)
            boolean hasOdd = false;
            for (int num : arr) {
                if (num % 2 != 0) {
                    hasOdd = true;
                    break;
                }
            }
            if (!hasOdd) {
                productOdd[0] = 0;
            }
        }

        System.out.println(sumEven[0] - productOdd[0]);
    }
}
